CREATE OR REPLACE FUNCTION Acc_TBU_Acc_fn() RETURNS TRIGGER AS $$
Declare
  nCount     NUMERIC := 0;
Begin
  If NEW.Type_Id=1 AND NEW.Type_Id!=OLD.Type_Id Then
    SELECT Count(*) INTO nCount FROM Acc_Trn WHERE Acc_Id=NEW.Id;
    If COALESCE(nCount,0)>0 Then
      RAISE EXCEPTION '%', 'There is Transactions on the Account Cannot Change Type to Head Account';
    End If;
  End If;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS Acc_TBU_Acc ON Acc_Acc;
CREATE TRIGGER Acc_TBU_Acc
  BEFORE UPDATE OF TYPE_ID
  ON Acc_Acc
  FOR EACH ROW
  EXECUTE FUNCTION Acc_TBU_Acc_fn();

