CREATE OR REPLACE FUNCTION Acc_TBU_Cost_fn() RETURNS TRIGGER AS $$
Declare
  nCount     NUMERIC := 0;
Begin
  If NEW.Type_Id=1 AND NEW.Type_Id!=OLD.Type_Id Then
    SELECT Count(*) INTO nCount FROM Acc_Trn WHERE Cost_Id=NEW.Id;
    If COALESCE(nCount,0)>0 Then
      RAISE EXCEPTION '%', 'There is Transactions on the Center Cannot Change Type to Head Center';
    End If;
  End If;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

