CREATE OR REPLACE FUNCTION Acc_TBID_Cost_fn() RETURNS TRIGGER AS $$
Declare
Begin
  If NEW.Id IS NULL Then
    SELECT nextval('Acc_Cost_Seq') Into NEW.Id;
  End If;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

